INSERT INTO `advice_templates` (`id`, `category`, `title`, `content`, `language`, `created_at`) VALUES
(1, 'general', 'Diet Advice - Bengali', 'কম তেল-মসলা জাতীয় খাবার খাবেন।\nবাহিরের ভাজা-পোড়া খাবার খাবেন না।\nরাতে হালকা খাবার খাবেন।\nখাওয়ার পরপর শুইবেন না (কিছুক্ষণ পায়চারী করুন)।\nপর্যাপ্ত পানি পান করুন।', 'bn', '2026-06-17 06:16:00'),
(2, 'general', 'Exercise Advice - Bengali', 'সপ্তাহে ৫ দিন ৩০-৪০ মিনিট করে জোরে হাঁটবেন।\nহালকা ব্যায়াম করুন।\nপ্রতিদিন সকালে ১৫ মিনিট হাঁটাহাঁটি করুন।', 'bn', '2026-06-17 06:16:00'),
(3, 'general', 'Diet Advice - English', 'Eat less oily and spicy food.\nAvoid outside fried food.\nEat light meal at night.\nWalk for 10-15 minutes after meal.\nDrink adequate water.', 'en', '2026-06-17 06:16:00'),
(4, 'general', 'Exercise Advice - English', 'Walk briskly for 30-40 minutes, 5 days a week.\nDo light exercises.\nWalk for 15 minutes every morning.', 'en', '2026-06-17 06:16:00'),
(5, 'diabetes', 'Diabetes Advice - Bengali', 'নিয়মিত রক্তের সুগার পরীক্ষা করান।\nমিষ্টি জাতীয় খাবার পরিহার করুন।\nডায়াবেটিক ডায়েট মেনে চলুন।\nনির্ধারিত সময়ে ঔষধ সেবন করুন।', 'bn', '2026-06-17 06:16:00'),
(6, 'diabetes', 'Diabetes Advice - English', 'Check blood sugar regularly.\nAvoid sugary foods.\nFollow diabetic diet.\nTake medications on time.', 'en', '2026-06-17 06:16:00'),
(7, 'hypertension', 'Hypertension Advice - Bengali', 'নিয়মিত BP পরীক্ষা করান।\nলবণ কম খাবেন।\nমানসিক চাপ কমানোর চেষ্টা করুন।\nওজন নিয়ন্ত্রণে রাখুন।', 'bn', '2026-06-17 06:16:00'),
(8, 'hypertension', 'Hypertension Advice - English', 'Check BP regularly.\nReduce salt intake.\nManage stress.\nMaintain healthy weight.', 'en', '2026-06-17 06:16:00');
